-- Owner sheet rows 150–154 and direct decisions of 21-Oct-2026.
UPDATE courses SET sales_page='{"version": 1, "hero": {"title": "Profitable Private Practices", "titleAccent": "Training for Clinically-Aligned Private Practices", "subtitle": "Build a practice that supports both your clients and your professional sustainability.", "highlights": ["4 Core CE Hours", "On-demand • Intermediate", "$149 • Lifetime access"], "image": {"src": "/images/ppp-training/banner.webp", "alt": "Profitable Private Practices training with Yvette Howard, LCSW", "width": 1281, "height": 623}}, "sections": [{"title": "Training Details", "list": ["CE Hours Included: 4 Core Hours", "Format: On-Demand Training (Asynchronous Learning) — Watch at your own pace. Pause, rewind, and revisit the material anytime.", "Investment: $149 (LIFETIME access!)", "Presented by: Yvette Howard, LCSW", "Instruction Level: Intermediate", "Target Audience: Licensed Mental Health Professionals, including Social Workers, Counselors, Marriage & Family Therapists, Psychologists, Pre-licensed Therapists, and other Behavioral Health Providers"]}, {"title": "Workshop Description", "paragraphs": ["Launching a private practice can be both liberating and overwhelming for mental health professionals. While graduate school prepares us to serve clients, it often leaves gaps in the business and ethical side of building a sustainable practice.", "This comprehensive training bridges that gap. We’ll cover the essential components of establishing a legally sound, ethically responsible, and clinically-aligned private practice. From deciding between practice models and setting session fees, to building your brand and streamlining your systems — you’ll walk away with clarity and a practical roadmap.", "Through downloadable template and real-life examples, you’ll learn how to build a business that supports both your clients'' needs and your professional sustainability. This course is ideal for clinicians who want to start private practice the right way, without compromising care, access, or ethical integrity."]}, {"title": "Educational Objectives", "intro": "In this workshop, you will learn how to:", "list": ["Identify the legal, ethical, and financial components necessary to launch a private mental health practice.", "Design a comprehensive business plan that includes niche definition, branding, pricing, and administrative systems.", "Formulate marketing, client onboarding, and retention strategies to attract and serve their ideal clientele.", "Explain the implications of insurance credentialing, private pay models, and documentation best practices."]}, {"title": "Presented by: Yvette Howard, LCSW", "paragraphs": ["Yvette is a Licensed Clinical Social Worker, business strategist, and private practice mentor with over 8 years of experience in the mental health field. She is the founder of Brighter Tomorrow Therapy — a thriving group practice — and the creator of Boss Builders Collective , where she coaches therapists to launch and scale private practices with confidence and clarity. Yvette holds a Master’s in Social Work and is currently completing her Doctorate in Organizational Leadership.", "Having gone from burnt-out employee to empowered practice owner, she now helps other clinicians do the same — without sacrificing ethics, access, or clinical quality. Her passion lies in demystifying the private practice process for therapists who are ready to lead with integrity and profit with purpose."], "image": {"src": "/images/ppp-training/yvette.jpeg", "alt": "Yvette Howard, LCSW", "width": 999, "height": 1440}}, {"title": "Questions and Program Policies", "paragraphs": ["For questions about this training, contact yvette@profitableprivatepractices.com.", "Review the [Continuing Education Program Policies](/continuing-education-boss-clinician)."]}], "footer": "Profitable Private Practices • On-demand training • Lifetime access"}'::jsonb,updated_at=now() WHERE slug='profitable-private-practices-training';
UPDATE courses SET sales_page='{"version": 1, "hero": {"title": "The Do’s & Don’ts of Clinical Documentation", "titleAccent": "Ethical, Legal & Audit-Ready Records", "subtitle": "Stop second-guessing your clinical notes. Learn how to document with clarity, confidence, and clinical purpose.", "paragraphs": ["Your clinical documentation should tell the story of the care you provide without requiring you to write a novel after every session.", "But are your notes actually supporting medical necessity? Would they hold up during an insurance audit, board investigation, or records request?", "In this practical, on-demand training, Yvette Howard, LCSW, breaks down the documentation habits that protect your clients, support ethical care, and help you avoid common mistakes that put your practice at risk."], "highlights": ["Self-paced, on-demand", "$99 one-time payment", "3.5 Ethics CE hours — subject to final approval"]}, "sections": [{"title": "Training Details", "list": ["Format: Self-paced, on-demand", "Continuing Education: 3.5 CE contact hours (Ethics), subject to final approval of this on-demand offering", "Price: $99", "Instructor: Yvette Howard, LCSW", "Audience: Licensed and pre-licensed therapists, clinical supervisors, and behavioral health professionals"]}, {"title": "What You’ll Learn", "intro": "By the end of this training, you’ll be able to:", "list": ["Identify common documentation mistakes that create ethical, legal, and audit risks.", "Understand what makes a progress note clinically defensible and supports medical necessity.", "Document high-risk situations, crisis services, and clinical decision-making appropriately.", "Recognize ethical considerations involving AI-assisted documentation, HIPAA, and client consent.", "Understand how documentation requirements relate to insurance audits, payer expectations, and billing.", "Connect assessments, treatment plans, progress notes, and outcome measures to demonstrate the clinical story."]}, {"title": "What’s Covered Inside the Training", "paragraphs": ["**1. Ethical Documentation Foundations** — Understand the difference between documenting too much, too little, and what actually matters.", "**2. Progress Notes & Medical Necessity** — Learn how to strengthen SOAP and DAP notes by clearly connecting symptoms, interventions, client responses, and treatment goals.", "**3. High-Risk & Crisis Documentation** — Explore how to document risk assessments, safety planning, mandated reporting, and crisis services without relying on vague or fear-based language.", "**4. Legal, HIPAA & Telehealth Considerations** — Review documentation practices related to records requests, subpoenas, corrections, confidentiality, and telehealth services.", "**5. AI-Assisted Clinical Documentation** — Understand the ethical responsibilities involved in using AI tools, including clinician oversight, HIPAA considerations, and client consent.", "**6. Insurance Audits & Documentation Compliance** — Identify common audit triggers, understand payer-specific expectations, and learn how to approach documentation reviews and corrections.", "**7. SOAP/DAP Notes, Treatment Plans & Outcome Measures** — Learn how to connect assessment findings, measurable treatment goals, progress notes, and standardized outcome measures to support clinical decision-making."]}, {"title": "Who This Training Is For", "intro": "This training is for you if:", "list": ["You spend too much time writing notes because you’re unsure what’s necessary.", "You want your documentation to better support medical necessity and continued treatment.", "You’re concerned about insurance audits or documentation being reviewed.", "You use AI-assisted documentation and want to understand your ethical responsibilities.", "You’re a practice owner or supervisor who wants stronger documentation standards.", "You need continuing education that offers practical information you can apply in your clinical work."]}, {"title": "Your Instructor", "intro": "Yvette Howard, LCSW", "paragraphs": ["Yvette is a licensed clinical social worker, clinical supervisor, private practice owner, and founder of Boss Clinician.", "After navigating insurance and Medicaid audits in her own practice, she developed a deeper understanding of what makes clinical documentation clear, defensible, and consistent with professional expectations.", "She brings real-world clinical and business experience to this training, helping therapists move beyond simply completing notes and toward documenting with intention."]}, {"title": "How to Earn Your CE Credit", "list": ["Watch the required training recordings, including the Documentation Deep Dive.", "Complete the post-training examination and achieve the required passing score.", "Submit the course evaluation.", "Receive your CE certificate after successful completion and verification of all applicable requirements."], "notes": ["Continuing education approval details, required passing score, and certificate procedures will be provided according to the approved on-demand program."]}, {"title": "Ready to Document With Confidence?", "paragraphs": ["You don’t need longer notes. You need documentation that clearly communicates your clinical judgment, supports the care you provide, and meets applicable professional and payer requirements.", "Enroll Today — $99", "Get access to the on-demand training and take the next step toward clearer, more confident clinical documentation."]}]}'::jsonb,updated_at=now() WHERE slug='dos-and-donts-of-clinical-documentation-replay';

UPDATE courses SET price_text='$77',updated_at=now() WHERE slug='audit-proof-your-practice-on-demand';
UPDATE courses SET price_text='$99',updated_at=now() WHERE slug='dos-and-donts-of-clinical-documentation-replay';
UPDATE offers SET amount_cents=9900,stripe_price_id=NULL,updated_at=now() WHERE slug='dos-and-donts-of-clinical-documentation-replay-free' AND amount_cents<>9900;
UPDATE offers SET description='## The Do’s & Don’ts of Clinical Documentation
### Ethical, Legal & Audit-Ready Records

Learn how to write clearer, clinically defensible notes, support medical necessity, avoid common documentation mistakes, and strengthen your confidence when navigating audits and payer requirements.

Your $99 enrollment includes:
- Self-paced access to the clinical documentation training and supplemental Deep Dive
- Practical clinical examples and documentation guidance
- Post-training exam and evaluation
- CE certificate upon successful completion of applicable requirements

**One-Time Payment: $99**

Continuing Education: 3.5 CE contact hours (Ethics), subject to final approval of this on-demand offering.
',checkout_headline='Ethical, Legal & Audit-Ready Records',updated_at=now() WHERE slug='dos-and-donts-of-clinical-documentation-replay-free';

INSERT INTO products(slug,title,kind,status,description)
VALUES('audit-ready-documentation-toolkit','Audit-Ready Documentation Toolkit','download','published','A 27-page resource with SOAP/DAP note templates, completed examples, an audit-readiness checklist, and a sample treatment plan.')
ON CONFLICT(slug) DO NOTHING;
INSERT INTO product_files(product_id,title,description,storage_path,filename,mime)
SELECT id,'Open your Audit-Ready Documentation Toolkit','Make your own copy in Google Docs.','https://docs.google.com/document/d/1-6Eot1t9ygeUCY9-DfLD5Ol9JvtfTDYiPy9QK7oN_mw/copy?usp=drive_link','Audit-Ready Documentation Toolkit','text/uri-list'
FROM products WHERE slug='audit-ready-documentation-toolkit' AND NOT EXISTS(SELECT 1 FROM product_files WHERE product_id=products.id);
INSERT INTO offer_bumps(offer_id,product_id,title,description,amount_cents,sort)
SELECT o.id,p.id,'Yes! Add the Audit-Ready Documentation Toolkit to my enrollment for $67.','Get a 27-page resource with SOAP/DAP note templates, completed examples, an audit-readiness checklist, and a sample treatment plan.',6700,0
FROM offers o CROSS JOIN products p WHERE o.slug='dos-and-donts-of-clinical-documentation-replay-free' AND p.slug='audit-ready-documentation-toolkit'
AND NOT EXISTS(SELECT 1 FROM offer_bumps b WHERE b.offer_id=o.id AND b.product_id=p.id);

-- The supplied letter collection belongs to its own paid course, not PPP.
INSERT INTO course_modules(course_id,title,summary,sort)
SELECT id,'Insurance Rate Increase Letter Templates','Copy and customize the templates for your insurance panels.',0 FROM courses c
WHERE slug='rate-negotiation-letter-template' AND NOT EXISTS(SELECT 1 FROM course_modules WHERE course_id=c.id);
INSERT INTO course_lessons(module_id,title,slug,content_type,body_md,published,sort)
SELECT m.id,'Get Your Rate Negotiation Letters','get-your-rate-negotiation-letters','text',
$body$Open the template collection and make your own copy before editing.

**[Open Insurance Rate Increase Letter Templates](https://docs.google.com/document/d/1WHeddsqVR--husL7LbkASMtJ5UbTMwv-Mcy2a4ISfS0/copy?usp=sharing)**

The collection includes a letter template for all insurance panels and a letter template for Cigna/Evernorth. Send your completed letter to the provider representative for the insurer you are negotiating with.$body$,true,0
FROM course_modules m JOIN courses c ON c.id=m.course_id WHERE c.slug='rate-negotiation-letter-template' AND m.title='Insurance Rate Increase Letter Templates'
AND NOT EXISTS(SELECT 1 FROM course_lessons WHERE module_id=m.id AND slug='get-your-rate-negotiation-letters');
INSERT INTO product_files(product_id,title,description,storage_path,filename,mime)
SELECT id,'Insurance Rate Increase Letter Templates','Make a copy to customize the letters for your panels.','https://docs.google.com/document/d/1WHeddsqVR--husL7LbkASMtJ5UbTMwv-Mcy2a4ISfS0/copy?usp=sharing','Insurance Rate Increase Letter Templates','text/uri-list'
FROM products p WHERE slug='rate-negotiation-letter-template' AND NOT EXISTS(SELECT 1 FROM product_files WHERE product_id=p.id);

-- Owner removed the separate cheat-sheet bonus: the workbook contains it.
UPDATE offers SET description=regexp_replace(description,'[^\n]*Pricing Formula Cheat Sheet[^\n]*','', 'gi'),updated_at=now()
WHERE slug='private-practice-starter-suite' AND description ILIKE '%Pricing Formula Cheat Sheet%';
UPDATE courses SET features=COALESCE((SELECT jsonb_agg(v) FROM jsonb_array_elements(features) v WHERE v::text NOT ILIKE '%cheat sheet%'),'[]'::jsonb),updated_at=now()
WHERE slug='private-practice-starter-suite' AND features::text ILIKE '%cheat sheet%';
UPDATE offer_pricing_options SET active=false,updated_at=now() WHERE offer_id=(SELECT id FROM offers WHERE slug='from-profile-to-profit') AND pricing_type<>'one_time';

UPDATE course_lessons SET body_md=$body$Use your private Practice Elevation Growth Dashboard below.

- Complete the 14-question Growth Assessment to choose a starting pathway.
- Edit three measurable goals and use the twelve weekly action workspaces.
- Enter Numbers & Goals once; matching primary-goal values stay connected while your custom entries are preserved.
- Prepare your Lounge Strategy Session question and record your takeaway and commitment.
- Review your results each month and keep your archived cycles, readable plan, and full data export.

Your entries save to your own member account and sync across devices. Check the save status before leaving. Do not enter client-identifying health information.$body$,updated_at=now()
WHERE tool_key='practice-elevation-dashboard';
